cat << 'EOF' > /workspace/generate_summary.js
const { Document, Packer, Paragraph, Table, TableRow, TableCell, TextRun, WidthType, AlignmentType, BorderStyle, HeadingLevel } = require("docx");
const fs = require("fs");

// Inventory data
const products = [
  { id: "PROD-B98D14", name: "Anker Portable Bluetooth Speaker", category: "Electronics", price: 79 },
  { id: "PROD-FA0948", name: "LogiTech Wireless Mouse M310", category: "Electronics", price: 29 },
  { id: "PROD-2DBA15", name: "Wireless Ergonomic Mouse", category: "Electronics", price: 39 },
  { id: "PROD-3E35A7", name: "OXO SoftWorks 3-Piece Mixing Bowl Set", category: "Kitchen", price: 42 },
  { id: "PROD-B416AA", name: "ThermoPro Digital Meat Thermometer", category: "Kitchen", price: 26 },
  { id: "PROD-7C0240", name: "Wireless Mouse", category: "Electronics", price: 29 },
  { id: "PROD-39F904", name: "Levi's Classic Cotton T-Shirt", category: "Clothing", price: 24 },
  { id: "PROD-190CB7", name: "OXO Good Grips Salad Spinner", category: "Kitchen", price: 38 },
  { id: "PROD-73FAB4", name: "Aurora Smart Desk Lamp Pro", category: "Electronics", price: 88 },
  { id: "PROD-7583E5", name: "CableCraft USB-C Organizer Strap 2-Pack", category: "Accessories", price: 16 },
  { id: "PROD-4316AC", name: "OXO Compact Electric Milk Frother", category: "Kitchen", price: 49 },
  { id: "PROD-9559B3", name: "Bamboo Desk Organizer Set", category: "Home Office", price: 34 },
  { id: "PROD-F9994E", name: "Harbor Cotton Crew Tee", category: "Apparel", price: 49 },
  { id: "PROD-93D48F", name: "RidgeLine Fleece Zip Hoodie", category: "Apparel", price: 89 },
  { id: "PROD-B7C77D", name: "Metro Stretch Chino Pants", category: "Apparel", price: 72 },
  { id: "PROD-AFC284", name: "TrailPeak Insulated Travel Mug", category: "Kitchen", price: 72 },
  { id: "PROD-FA349F", name: "Northline Wool Blend Throw Blanket", category: "Home", price: 34 },
  { id: "PROD-4ED2E3", name: "Everyday Canvas Tote Bag", category: "Accessories", price: 28 },
  { id: "PROD-4809AA", name: "AUTUMN10 Cart Discount", category: "Promotion", price: 0 },
  { id: "PROD-FCFD98", name: "AeroLoop Silicone Cable Organizer", category: "Accessories", price: 14 },
];

// Compute stats
const totalItems = products.length;
const categories = [...new Set(products.map(p => p.category))];
const prices = products.filter(p => p.price > 0).map(p => p.price);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const avgPrice = (prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2);

// Category breakdown
const catCounts = {};
categories.forEach(c => { catCounts[c] = products.filter(p => p.category === c).length; });

// Helper: bold cell
const boldCell = (text, shading) => new TableCell({
  children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 20, font: "Calibri" })] })],
  shading: shading ? { fill: "2E75B6" } : undefined,
  width: { size: 25, type: WidthType.PERCENTAGE },
});

const textCell = (text) => new TableCell({
  children: [new Paragraph({ children: [new TextRun({ text, size: 20, font: "Calibri" })] })],
  width: { size: 25, type: WidthType.PERCENTAGE },
});

// Build table
const headerRow = new TableRow({
  children: [
    boldCell("Product ID", true),
    boldCell("Name", true),
    boldCell("Category", true),
    boldCell("Price ($)", true),
  ],
});

const dataRows = products.map(p => new TableRow({
  children: [
    textCell(p.id),
    textCell(p.name),
    textCell(p.category),
    textCell(p.price === 0 ? "—" : `$${p.price}`),
  ],
}));

const catBreakdown = Object.entries(catCounts)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, count]) => `${cat}: ${count}`)
  .join(", ");

const doc = new Document({
  sections: [{
    children: [
      // Title
      new Paragraph({
        heading: HeadingLevel.HEADING_1,
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Product Inventory Summary", bold: true, size: 32, font: "Calibri" })],
      }),
      // Date
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 300 },
        children: [new TextRun({ text: `Generated on: ${new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" })}`, italics: true, size: 20, font: "Calibri", color: "666666" })],
      }),
      // Overview heading
      new Paragraph({
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200 },
        children: [new TextRun({ text: "Overview", bold: true, size: 26, font: "Calibri" })],
      }),
      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({ text: `This inventory contains `, size: 22, font: "Calibri" }),
                   new TextRun({ text: `${totalItems} products`, bold: true, size: 22, font: "Calibri" }),
                   new TextRun({ text: ` spanning `, size: 22, font: "Calibri" }),
                   new TextRun({ text: `${categories.length} categories`, bold: true, size: 22, font: "Calibri" }),
                   new TextRun({ text: `. All listed items are currently marked as `, size: 22, font: "Calibri" }),
                   new TextRun({ text: `In Stock`, bold: true, size: 22, font: "Calibri" }),
                   new TextRun({ text: `.`, size: 22, font: "Calibri" })],
      }),
      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({ text: `Price range: $${minPrice} – $${maxPrice}  |  Average price: $${avgPrice}`, size: 22, font: "Calibri" })],
      }),
      new Paragraph({
        spacing: { after: 200 },
        children: [new TextRun({ text: `Category breakdown — ${catBreakdown}.`, size: 22, font: "Calibri" })],
      }),
      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({ text: `Note: One entry (PROD-4809AA, "AUTUMN10 Cart Discount") is a promotional discount code, not a physical product.`, italics: true, size: 20, font: "Calibri", color: "888888" })],
      }),
      // Product listing heading
      new Paragraph({
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 300 },
        children: [new TextRun({ text: "Product Listing", bold: true, size: 26, font: "Calibri" })],
      }),
      // Table
      new Table({
        rows: [headerRow, ...dataRows],
        width: { size: 100, type: WidthType.PERCENTAGE },
      }),
    ],
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/workspace/data/product_inventory_summary.docx", buffer);
  console.log("Document saved successfully to data/product_inventory_summary.docx");
});
